#include <iostream>
#include <string>
#include <stdexcept>

int main() {
    std::string s1{"happy"};
    std::string s2{" birthday"};
    std::string s3;

    if (s3.empty()) {
        s3 = s1; // Copy assignment
    }

    s1 += s2;           // s1 becomes "happy birthday"
    s1 += " to you";    // Append literal

    std::cout << "s1: " << s1 << "\n";
    std::cout << "s3: " << s3 << "\n";
    std::cout << "s1.substr(0, 14): " << s1.substr(0, 14) << "\n";
    std::cout << "s1.substr(15): " << s1.substr(15) << "\n";

    // Using operator[] as lvalue
    s1[0] = 'H';
    s1[6] = 'B';
    std::cout << "Modified s1: " << s1 << "\n";

    // Demonstrating bounds checking with at()
    try {
        s1.at(50) = '!';
    } catch (const std::out_of_range& ex) {
        std::cout << "Caught exception: " << ex.what() << "\n";
    }

    return 0;
}

#include <iostream>

class Vector2D {
private:
    double x{0.0};
    double y{0.0};

public:
    Vector2D() = default;
    Vector2D(double px, double py) : x(px), y(py) {}

    // Mandatory member operator: compound assignment
    Vector2D& operator+=(const Vector2D& rhs) {
        x += rhs.x;
        y += rhs.y;
        return *this;
    }

    // Unary negation operator -
    Vector2D operator-() const {
        return Vector2D(-x, -y);
    }

    void print() const {
        std::cout << "(" << x << ", " << y << ")";
    }
};

// Binary + as non-member function implemented via +=
Vector2D operator+(Vector2D lhs, const Vector2D& rhs) {
    lhs += rhs;
    return lhs;
}

int main() {
    Vector2D v1(2.5, 3.5);
    Vector2D v2(1.0, -1.0);

    Vector2D sum = v1 + v2; // Calls operator+(v1, v2)
    Vector2D neg = -v1;     // Calls v1.operator-()

    std::cout << "sum: ";
    sum.print();
    std::cout << "\nnegated v1: ";
    neg.print();
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <sstream>
#include <iomanip>

class PhoneNumber {
    // Friend non-member declarations for stream I/O
    friend std::ostream& operator<<(std::ostream& output, const PhoneNumber& num);
    friend std::istream& operator>>(std::istream& input, PhoneNumber& num);

private:
    std::string areaCode;
    std::string exchange;
    std::string line;

public:
    PhoneNumber() = default;
};

std::ostream& operator<<(std::ostream& output, const PhoneNumber& num) {
    output << "(" << num.areaCode << ") " << num.exchange << "-" << num.line;
    return output; // Enables chaining
}

std::istream& operator>>(std::istream& input, PhoneNumber& num) {
    input.ignore(); // Skip opening '('
    input >> std::setw(3) >> num.areaCode;
    input.ignore(2); // Skip ") "
    input >> std::setw(3) >> num.exchange;
    input.ignore(); // Skip '-'
    input >> std::setw(4) >> num.line;
    return input; // Enables chaining
}

int main() {
    std::istringstream testInput("(800) 555-1212");
    PhoneNumber phone;

    // Simulate input stream extraction: operator>>(testInput, phone)
    testInput >> phone;

    // Stream insertion: operator<<(std::cout, phone)
    std::cout << "Formatted Phone Number: " << phone << "\n";

    return 0;
}
